<?php
$e=[];foreach([__DIR__.'/.env','C:\\plantel\\DATOS_LOCALES\\plantel.env']as$p){if(is_readable($p))foreach((array)file($p,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)as$l){$l=trim($l);if($l===''||$l[0]==='#'||!str_contains($l,'='))continue;[$k,$v]=explode('=',$l,2);$e[trim($k)]=trim($v," \t\n\r\0\x0B\"'");}}
$g=function($k,$d='')use($e){$v=getenv($k);return$v!==false&&$v!==''?$v:($e[$k]??$d);};$err='';$rows=[];$periods=[];$target=$_GET['periodo']??date('Y-m');$target=preg_match('/^\d{6}$/',$target)?substr($target,0,4).'-'.substr($target,4,2):$target;$from=$_GET['desde']??'';$to=$_GET['hasta']??'';$fmt=function($v,$d=0){return number_format((float)$v,$d,',','.');};$label=function($v){$m=['01'=>'Enero','02'=>'Febrero','03'=>'Marzo','04'=>'Abril','05'=>'Mayo','06'=>'Junio','07'=>'Julio','08'=>'Agosto','09'=>'Septiembre','10'=>'Octubre','11'=>'Noviembre','12'=>'Diciembre'];return($m[substr($v,5,2)]??$v).' '.substr($v,0,4);};
try{$pdo=new PDO('mysql:host='.$g('DB_HOSTINGER_LAB_HOST').';port='.$g('DB_HOSTINGER_LAB_PORT','3306').';dbname='.$g('DB_HOSTINGER_LAB_DATABASE').';charset=utf8mb4',$g('DB_HOSTINGER_LAB_USER'),$g('DB_HOSTINGER_LAB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$periods=array_map(fn($r)=>substr($r['periodo'],0,4).'-'.substr($r['periodo'],4,2),$pdo->query("SELECT DISTINCT periodo FROM raw_dataflow_toa_instalaciones ORDER BY periodo DESC LIMIT 36")->fetchAll());$from=$from?:$target;$to=$to?:$target;$q=$pdo->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.zona22')) zona,JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.fecha_de_cita')) fecha,COUNT(*) altas FROM raw_dataflow_toa_instalaciones WHERE periodo BETWEEN ? AND ? GROUP BY zona,fecha");$q->execute([str_replace('-','',$from),str_replace('-','',$to)]);$cq=$pdo->prepare("SELECT JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.zona22')) zona,COUNT(*) realizadas FROM raw_dataflow_toa_instalaciones WHERE periodo=? AND UPPER(JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.estado_de_la_orden')))='COMPLETADO' AND LOWER(JSON_UNQUOTE(JSON_EXTRACT(datos_json,'$.alta'))) IN ('true','1','si','sí') GROUP BY zona");$cq->execute([str_replace('-','',$target)]);$current=[];foreach($cq as $cr)$current[(string)$cr['zona']]=(int)$cr['realizadas'];$z=['ZONA 1 - AMBA'=>['h'=>0,'s'=>0,'dh'=>[],'ds'=>[]],'ZONA 2 - LA PLATA'=>['h'=>0,'s'=>0,'dh'=>[],'ds'=>[]],'ZONA 3 - PROV. BS.AS'=>['h'=>0,'s'=>0,'dh'=>[],'ds'=>[]]];foreach($q as $r){if(!isset($z[$r['zona']]))continue;$d=DateTimeImmutable::createFromFormat('Y-m-d',substr(trim((string)$r['fecha']),0,10))?:DateTimeImmutable::createFromFormat('d/m/Y',substr(trim((string)$r['fecha']),0,10));if(!$d)continue;$k=$d->format('N')==='6'?'s':((int)$d->format('N')<6?'h':'');if(!$k)continue;$z[$r['zona']][$k]+=$r['altas'];$z[$r['zona']]['d'.($k==='h'?'h':'s')][$d->format('Y-m-d')]=1;}$o=is_readable('C:\\plantel\\matrix\\config\\objetivos_toa.json')?json_decode(file_get_contents('C:\\plantel\\matrix\\config\\objetivos_toa.json'),true):[];$c=$o[str_replace('-','',$target)]??[];$date=DateTimeImmutable::createFromFormat('!Y-m-d',$target.'-01');$dh=$c['dias_habiles']??0;$ds=$c['sabados']??0;if(!$dh||!$ds){$dh=$ds=0;for($i=0;$i<(int)$date->format('t');$i++){$n=$date->modify("+$i days")->format('N');if($n<6)$dh++;if($n==='6')$ds++;}}$nowPeriod=date('Y-m');$remainingH=$target>$nowPeriod?$dh:0;$remainingS=$target>$nowPeriod?$ds:0;$make=function($name,$list)use(&$z,&$current,$remainingH,$remainingS,$c){$h=$s=0;$hd=[];$sd=[];foreach($list as $x){$h+=$z[$x]['h'];$s+=$z[$x]['s'];$hd+=$z[$x]['dh'];$sd+=$z[$x]['ds'];}$ah=count($hd)?$h/count($hd):0;$as=count($sd)?$s/count($sd):0;$actual=$name==='Zona 3'?($current['ZONA 3 - PROV. BS.AS']??0):(($current['ZONA 1 - AMBA']??0)+($current['ZONA 2 - LA PLATA']??0));$p=$actual+$ah*$remainingH+$as*$remainingS;$goal=$name==='Zona 3'?($c['zona3']??0):($c['zona12']??0);return compact('name','ah','as','p','goal')+['diff'=>$p-$goal,'historical'=>$h+$s];};$rows=[$make('Zona 3',['ZONA 3 - PROV. BS.AS']),$make('Zona 1 + 2',['ZONA 1 - AMBA','ZONA 2 - LA PLATA'])];$state=$pdo->query("SELECT ultima_fecha_hora_actualizacion FROM automatizaciones_estado WHERE nombre_automatizacion='dataflow_toa_instalaciones' LIMIT 1")->fetch()?:[];}catch(Throwable$x){$err=$x->getMessage();}$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$pt=array_sum(array_column($rows,'p'));$gt=array_sum(array_column($rows,'goal'));$done=array_sum($current);?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proyección de altas</title><style>body{margin:0;background:#e8f0f3;color:#172033;font:14px system-ui,sans-serif}main{padding:22px;max-width:1320px;margin:auto}.head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:18px}h1{margin:0;font-size:26px}.sub,.note{color:#647589;font-size:12px}.updated{color:#066a75;font-weight:700;font-size:12px;margin-top:8px}.filters,.card,.box{background:#fff;border:1px solid #c5d5de;border-radius:9px}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap;padding:12px}label{display:grid;gap:4px;color:#415063;font-size:11px;font-weight:700}select,button{height:36px;border-radius:7px;font:inherit}select{border:1px solid #c5d5de;padding:0 8px}button{border:1px solid #087f8c;background:#087f8c;color:#fff;padding:0 15px;font-weight:700}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:12px}.card{padding:13px 15px}.card span{display:block;color:#647589;font-size:11px;font-weight:700}.card strong{display:block;font-size:24px;margin-top:4px}.positive{color:#197044}.negative{color:#b42318}.box{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:11px 12px;border-bottom:1px solid #c5d5de;text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#e7f0f3;color:#174052;font-size:10px;text-transform:uppercase}tr:last-child td{border:0}.status{padding:4px 8px;border-radius:99px;font-weight:700}.ok{background:#e4f5ea;color:#197044}.no{background:#fff0ee;color:#b42318}@media(max-width:800px){.head{display:block}.filters{margin-top:14px}.cards{grid-template-columns:repeat(2,1fr)}select,button,label{width:100%}}</style></head><body><main><div class="head"><div><h1>Proyección de altas</h1><p class="sub">Estimación de instalaciones TOA por productividad histórica y calendario productivo.</p><div class="updated">Datos actualizados: <?=$esc($state['ultima_fecha_hora_actualizacion']??'sin dato')?></div></div><form class="filters"><label>Período objetivo<select name="periodo"><?php foreach($periods as $x):?><option value="<?=$esc($x)?>" <?=$x===$target?'selected':''?>><?=$esc($label($x))?></option><?php endforeach;?></select></label><label>Histórico desde<select name="desde"><?php foreach($periods as $x):?><option value="<?=$esc($x)?>" <?=$x===$from?'selected':''?>><?=$esc($label($x))?></option><?php endforeach;?></select></label><label>Histórico hasta<select name="hasta"><?php foreach($periods as $x):?><option value="<?=$esc($x)?>" <?=$x===$to?'selected':''?>><?=$esc($label($x))?></option><?php endforeach;?></select></label><button>Consultar</button></form></div><?php if($err):?><div><?=$esc($err)?></div><?php else:?><div class="cards"><div class="card"><span>Realizadas período actual</span><strong><?=$fmt($done)?></strong></div><div class="card"><span>Proyección total</span><strong><?=$fmt($pt)?></strong></div><div class="card"><span>Objetivo total</span><strong><?=$fmt($gt)?></strong></div><div class="card"><span>Diferencia</span><strong class="<?=$pt>=$gt?'positive':'negative'?>"><?=$pt>=$gt?'+':''?><?=$fmt($pt-$gt)?></strong></div><div class="card"><span>Calendario objetivo</span><strong><?=$fmt($dh)?> + <?=$fmt($ds)?></strong></div></div><div class="box"><table><tr><th>Grupo</th><th>Prom. lunes a viernes</th><th>Prom. sábado</th><th>Realizadas período</th><th>Altas históricas</th><th>Proyección</th><th>Objetivo</th><th>Diferencia</th><th>Resultado</th></tr><?php foreach($rows as $r):?><tr><td><b><?=$esc($r['name'])?></b></td><td><?=$fmt($r['ah'],1)?> / día</td><td><?=$fmt($r['as'],1)?> / sábado</td><td><?=$fmt(($r['name']==='Zona 3'?($current['ZONA 3 - PROV. BS.AS']??0):(($current['ZONA 1 - AMBA']??0)+($current['ZONA 2 - LA PLATA']??0))))?></td><td><?=$fmt($r['historical'])?></td><td><b><?=$fmt($r['p'])?></b></td><td><?=$fmt($r['goal'])?></td><td class="<?=$r['diff']>=0?'positive':'negative'?>"><?=$r['diff']>=0?'+':''?><?=$fmt($r['diff'])?></td><td><span class="status <?=$r['diff']>=0?'ok':'no'?>"><?=$r['diff']>=0?'Llega':'No llega'?></span></td></tr><?php endforeach;?></table></div><p class="note">Base histórica: <?=$esc($label($from))?> a <?=$esc($label($to))?>. Promedios calculados sobre días con instalaciones registradas.</p><?php endif;?></main></body></html>